namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDateUtc { get; set; }
    public DateTime EstimatedDeliveryUtc { get; set; }
    public DateTime? ActualDeliveryUtc { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string CustomerEmail { get; set; } = string.Empty;
    public double WeightKg { get; set; }
    public string Notes { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Returned
}

using System.ComponentModel.DataAnnotations;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; }

    public DateTime ShippedDateUtc { get; set; }
    public DateTime EstimatedDeliveryUtc { get; set; }
    public DateTime? ActualDeliveryUtc { get; set; }

    [Required, MaxLength(200)]
    public string RecipientName { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string CustomerEmail { get; set; } = string.Empty;

    public double WeightKg { get; set; }

    [MaxLength(1000)]
    public string Notes { get; set; } = string.Empty;

    public ShipmentDto ToDto() => new()
    {
        Id = Id,
        TrackingNumber = TrackingNumber,
        Origin = Origin,
        Destination = Destination,
        Status = Status,
        ShippedDateUtc = ShippedDateUtc,
        EstimatedDeliveryUtc = EstimatedDeliveryUtc,
        ActualDeliveryUtc = ActualDeliveryUtc,
        RecipientName = RecipientName,
        CustomerEmail = CustomerEmail,
        WeightKg = WeightKg,
        Notes = Notes
    };

    public static Shipment FromDto(ShipmentDto dto) => new()
    {
        Id = dto.Id,
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = dto.Status,
        ShippedDateUtc = dto.ShippedDateUtc,
        EstimatedDeliveryUtc = dto.EstimatedDeliveryUtc,
        ActualDeliveryUtc = dto.ActualDeliveryUtc,
        RecipientName = dto.RecipientName,
        CustomerEmail = dto.CustomerEmail,
        WeightKg = dto.WeightKg,
        Notes = dto.Notes
    };
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus);
    Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

/// <summary>
/// HTTP-based implementation used by the WebAssembly client.
/// </summary>
public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode)
            return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var response = await http.PatchAsJsonAsync($"api/shipments/{id}/status", newStatus);
        if (!response.IsSuccessStatusCode)
            return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation that accesses the database directly.
/// Used during interactive-server rendering (before WASM loads).
/// </summary>
public class ServerShipmentService(IDbContextFactory<ApplicationDbContext> dbFactory) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        await using var db = await dbFactory.CreateDbContextAsync();
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDateUtc)
            .Select(s => s.ToDto())
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        await using var db = await dbFactory.CreateDbContextAsync();
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment?.ToDto();
    }

    public async Task<ShipmentDto?> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        await using var db = await dbFactory.CreateDbContextAsync();
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return null;

        shipment.Status = newStatus;
        if (newStatus == ShipmentStatus.Delivered)
            shipment.ActualDeliveryUtc = DateTime.UtcNow;

        await db.SaveChangesAsync();
        return shipment.ToDto();
    }

