        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260701-10001)"
                   @bind="searchTracking" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isSearching">
                @if (isSearching)
                {
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                }
                else
                {
                    <span>Search</span>
                }
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedTracking</strong>.
        Please check and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Shipment <code>@shipment.TrackingNumber</code></h5>
            <span class="badge @GetStatusBadge(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row mb-4">
                <div class="col-md-6">
                    <h6>Route</h6>
                    <p class="fs-5">@shipment.Origin → @shipment.Destination</p>
                </div>
                <div class="col-md-6">
                    <h6>Recipient</h6>
                    <p class="fs-5">@shipment.RecipientName</p>
                </div>
            </div>

            <div class="row mb-4">
                <div class="col-md-4">
                    <h6>Shipped Date</h6>
                    <p>@shipment.ShippedDateUtc.ToString("MMMM dd, yyyy")</p>
                </div>
                <div class="col-md-4">
                    <h6>Estimated Delivery</h6>
                    <p class="fw-bold text-primary">@shipment.EstimatedDeliveryUtc.ToString("MMMM dd, yyyy")</p>
                </div>
                <div class="col-md-4">
                    @if (shipment.ActualDeliveryUtc.HasValue)
                    {
                        <h6>Actual Delivery</h6>
                        <p class="fw-bold text-success">@shipment.ActualDeliveryUtc.Value.ToString("MMMM dd, yyyy HH:mm") UTC</p>
                    }
                    else
                    {
                        <h6>Days Until Estimated Delivery</h6>
                        @{
                            var daysLeft = (shipment.EstimatedDeliveryUtc - DateTime.UtcNow).Days;
                        }
                        <p class="fw-bold @(daysLeft < 0 ? "text-danger" : "text-info")">
                            @if (daysLeft < 0)
                            {
                                @($"{Math.Abs(daysLeft)} day(s) overdue")
                            }
                            else
                            {
                                @($"{daysLeft} day(s)")
                            }
                        </p>
                    }
                </div>
            </div>

            <!-- Progress tracker -->
            <h6>Shipment Progress</h6>
            <div class="progress mb-3" style="height: 30px;">
                <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                     role="progressbar"
                     style="width: @(GetProgressPercent(shipment.Status))%"
                     aria-valuenow="@GetProgressPercent(shipment.Status)"
                     aria-valuemin="0" aria-valuemax="100">
                    @shipment.Status
                </div>
            </div>

            <div class="d-flex justify-content-between text-muted small">
                <span>Pending</span>
                <span>Picked Up</span>
                <span>In Transit</span>
                <span>Out for Delivery</span>
                <span>Delivered</span>
            </div>

            @if (!string.IsNullOrWhiteSpace(shipment.Notes))
            {
                <div class="mt-3">
                    <h6>Notes</h6>
                    <p class="text-muted">@shipment.Notes</p>
                </div>
            }
        </div>
    </div>
}

@code {
